// API addresses for the three services. The site holds no keys of any kind:
// the services are called with the user's login token only.
//
// On Floci (the site is served from http://localhost:4566/club-web/) and
// with the local dev server, the addresses come from shared/config.local.js,
// generated by `npm run config:local` and ignored by Git, because each Floci
// deployment gets its own API id.

const EMPTY = {
  membership: { apiUrl: "" },
  events: { apiUrl: "" },
  announcements: { apiUrl: "" },
};

const isLocal = ["localhost", "127.0.0.1"].includes(location.hostname);

let selected = EMPTY;
if (isLocal) {
  try {
    selected = (await import("./config.local.js")).default;
  } catch {
    selected = EMPTY;
  }
}

function freezeDeep(obj) {
  for (const value of Object.values(obj)) {
    if (value && typeof value === "object") freezeDeep(value);
  }
  return Object.freeze(obj);
}

export const config = freezeDeep(structuredClone(selected));

// True when a service has an address configured.
export function isConfigured(service) {
  return Boolean(config[service]?.apiUrl);
}
